from pathlib import Path
from html.parser import HTMLParser
import hashlib, json, re

class SupportPage(HTMLParser):
    def __init__(self):
        super().__init__()
        self.text = []
        self.links = []
        self.hidden = False
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.hidden = True
        if tag == 'a' and not self.hidden:
            url = dict(attrs).get('href') or ''
            if not url.startswith('mailto:') and re.search(r'submit|contribut|tool|support', url, re.I):
                self.links.append(url)
    def handle_endtag(self, tag):
        if tag in ('script', 'style'):
            self.hidden = False
    def handle_data(self, text):
        if not self.hidden and text.strip():
            self.text.append(' '.join(text.split()))

base = Path('products/distribution/sqlite-related-tools-referral')
raw = (base / 'raw/sqlite-official-support.html').read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == '002a8f484a5f8b3048a7361fe29b2721ca96c5ab7be8743a8dc8b4299f70fc02'
page = SupportPage()
page.feed(raw.decode('utf-8'))
text = ' '.join(page.text)
pattern = r'\b(?:submit(?:s|ted|ting)?|submission(?:s)?|contribut\w*|third.party|list(?:ing)?s?|commercial support|professional support|paid support|support options)\b'
excerpts = list(dict.fromkeys(text[max(0, match.start()-70):match.end()+110] for match in re.finditer(pattern, text, re.I)))
result = {'source': 'https://sqlite.org/support.html', 'capture_task': 'TASK-179549676100', 'sha256': digest, 'excerpts': excerpts[:35], 'candidate_links': list(dict.fromkeys(page.links))[:35], 'coverage': 'Keyword excerpts and candidate links from one support page. Read the full page before deciding whether SQLite invites third-party tool listings.'}
output = json.dumps(result, ensure_ascii=False, indent=2) + '\n'
(base / 'support-route-excerpts.json').write_text(output, encoding='utf-8')
print(output)
